const menu=document.querySelector('.menu'),nav=document.querySelector('#navigation'),lang=document.querySelector('.lang');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});lang.addEventListener('click',()=>{const en=document.documentElement.lang==='es';document.documentElement.lang=en?'en':'es';document.querySelectorAll('[data-es]').forEach(el=>el.innerHTML=el.dataset[en?'en':'es']);lang.textContent=en?'ES':'EN';lang.setAttribute('aria-label',en?'Cambiar idioma a español':'Switch language to English');nav.setAttribute('aria-label',en?'Main navigation':'Navegación principal');document.title=en?'ARTI — Entertainment that connects':'ARTI — Entretenimiento que conecta'});
const labels=[['Consultar entretenimiento corporativo','Ask about corporate entertainment'],['Consultar entretenimiento para hoteles','Ask about hotel entertainment'],['Conocer shows interactivos','Explore interactive shows'],['Consultar coordinación audiovisual','Ask about audiovisual coordination'],['Consultar eventos especiales','Ask about special events']];lang.addEventListener('click',()=>{const en=document.documentElement.lang==='en';document.querySelector('.skip').textContent=en?'Skip to content':'Saltar al contenido';document.querySelector('.wordmark').setAttribute('aria-label',en?'Arti Creative Group, home':'Arti Creative Group, inicio');document.querySelectorAll('.service-list article a').forEach((a,i)=>a.setAttribute('aria-label',labels[i][en?1:0]))});if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.1});document.querySelectorAll('.section-head,.service-list article,.manifesto-grid,.guest-grid,.tech,.future-grid article,.process ol').forEach(el=>{el.classList.add('reveal');observer.observe(el)})}
